export function translateUI(text,language){if(language!=='hi')return text;const trimmed=text.trim();let t=HI[trimmed];if(t===undefined){t=trimmed.replace(/^Grade (\d+)/,'कक्षा $1').replace(/^Week (\d+) · Day (\d+)$/,'सप्ताह $1 · दिवस $2').replace(/^Week (\d+)$/,'सप्ताह $1').replace(/^Day (\d+)$/,'दिवस $1').replace(/^Topic (\d+)$/,'विषय $1').replace(/^(\d+) sub-topics$/,'$1 उपविषय').replace(/^(\d+) learning outcomes?$/,'$1 सीखने का प्रतिफल').replace(/^(\d+) lessons?$/,'$1 पाठ').replace(/^Step (\d+) of (\d+)$/,'चरण $1 / $2').replace(/^(\d+) periods · (\d+) min$/,'$1 कालांश · $2 मिनट').replace(/^(\d+) min$/,'$1 मिनट').replace(/^Topic: /,'विषय: ').replace(/^(\d+) periods · (\d+) min lesson$/,'$1 कालांश · $2 मिनट का पाठ').replace(/min lesson$/,'मिनट का पाठ').replace(/printed page /,'संदर्शिका पृष्ठ ').replace(/PDF page /,'PDF पृष्ठ ').replace(/^Sub-topic: /,'उपविषय: ').replace(/^NIPUN learning outcome · /,'निपुण दक्षता · ').replace(/^Learning outcome · /,'सीखने का प्रतिफल · ').replace(/^Weekly plan · /,'साप्ताहिक योजना · ').replace(/^([1-6])\. I do$/,'$1. मैं करूँ').replace(/^([1-6])\. We do$/,'$1. हम करें').replace(/^([1-6])\. You do$/,'$1. आप करो');if(t==='Sub-topic')t='उपविषय';}
return text.replace(trimmed,t);}
